    One small detail: `_inPool.Remove(obj)` in `Rent` is only possible if `obj` was actually in the pool. Since `_pool.Dequeue()` only happens if `_pool.Count > 0`, and we ensure every item in `_pool` is also in `_inPool`, this is safe.

    ```csharp
    using UnityEngine;
    using System.Collections.Generic;

    public class ProjectilePool : MonoBehaviour
    {
        [SerializeField] private GameObject prefab;
        [SerializeField] private int prewarmCount;

        private readonly Queue<GameObject> _pool = new Queue<GameObject>();
        private readonly HashSet<GameObject> _inPool = new HashSet<GameObject>();

        private void Awake()
        {
            for (int i = 0; i < prewarmCount; i++)
            {
                GameObject obj = Instantiate(prefab, transform);
                obj.SetActive(false);
                _pool.Enqueue(obj);
                _inPool.Add(obj);
            }
        }

        public GameObject Rent()
        {
            GameObject obj;

            if (_pool.Count > 0)
            {
                obj = _pool.Dequeue();
                _inPool.Remove(obj);
            }
            else
            {
                obj = Instantiate(prefab, transform);
            }

            obj.SetActive(true);
            return obj;
        }

        public void Return(GameObject go)
        {
            if (go == null || _inPool.Contains(go))
            {
                return;
            }

            go.SetActive(false);
            _pool.Enqueue(go);
            _inPool.Add(go);
        }
    }
